<script lang="ts">
import {onMount} from 'svelte'; import {locations} from '../fixtures/locations'; import type {Profile} from '../domain/publication'; import {parseRoute} from './routeState'; import {filterLocations,initialFilters,type FilterState} from '../features/locations/filterState';
let profile:Profile='curated'; let scenario='ready'; let selected=locations[0]; let search=''; let region='all'; let category='all'; let filters:FilterState=initialFilters; $: filters={search,region,category}; $: source=profile==='community'?locations.slice(0,1):locations; $: visibleLocations=filterLocations(source,filters);
const syncRoute=()=>{const route=parseRoute(window.location.hash);if(route.kind==='location'){profile=route.profile;selected=locations.find((item)=>item.id===route.facilityId)??locations[0];}else if(route.kind==='home'){profile=route.profile;selected=locations[0];}}; const selectLocation=(id:string)=>{selected=locations.find((item)=>item.id===id)??selected;window.location.hash=`/locations/${id}?profile=${profile}`;}; onMount(()=>{syncRoute();window.addEventListener('hashchange',syncRoute);return()=>window.removeEventListener('hashchange',syncRoute);});
</script>
<svelte:head><title>Until Every Cage · evidence desk</title></svelte:head><main><header class="top"><a class="wordmark" href="/v2-preview/#/">UNTIL EVERY CAGE <span>V2 / FIELD NOTE</span></a><a href="/ethics.html">Ethics &amp; safeguards ↗</a></header><section class="intro"><p class="eyebrow">EVIDENCE DESK · SYNTHETIC PREVIEW</p><h1>See what a record can—and cannot—tell us.</h1><p class="lede">A quiet, inspectable view of animal-agriculture locations. Every fixture below is fictional, so you can examine the interface without exposing real places or people.</p></section>
<section class="toolbar" aria-label="Preview controls"><label>Profile<select bind:value={profile}><option value="curated">Curated release</option><option value="community">Community claims</option></select></label><label>Search locations<input aria-label="Search locations" bind:value={search} placeholder="Name, region, category" /></label><label>Region<select aria-label="Filter by region" bind:value={region}><option value="all">All regions</option>{#each [...new Set(locations.map((item)=>item.region))] as option}<option value={option}>{option}</option>{/each}</select></label><label>State<select bind:value={scenario}><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option><option value="error">Error</option><option value="restricted">Restricted</option></select></label><span class="release">Release <strong>synthetic-2026.09</strong></span></section>
{#if profile==='community'}<div class="warning" role="note"><strong>Unreviewed community claim</strong><span>Not verified by Until Every Cage. Privacy screening is separate from factual review.</span></div>{/if}{#if scenario==='loading'}<div class="state">Loading the fixture…</div>{:else if scenario==='empty'}<div class="state"><h2>No eligible records</h2><p>This profile has no records for the selected fixture.</p></div>{:else if scenario==='error'}<div class="state error" role="alert"><h2>Could not load preview</h2><p>The fixture could not be read. Try the ready state again.</p></div>{:else if scenario==='restricted'}<div class="state"><h2>Preview withheld</h2><p>This scenario represents restricted material. No restricted record is embedded in the demonstrator.</p></div>{:else}<div class="content"><aside><div class="list-head"><span>VISIBLE RECORDS</span><strong>{visibleLocations.length}</strong></div>{#each visibleLocations as location}<button class:active={selected?.id===location.id} onclick={()=>selectLocation(location.id)}><span class="dot"></span><span><strong>{location.name}</strong><small>{location.region} · {location.category}</small></span></button>{:else}<p class="no-match">No records match these filters.</p>{/each}</aside><article>{#if selected}<p class="eyebrow">RECORD / {selected.id}</p><h2>{selected.name}</h2><p class="region">{selected.region} · {selected.category}</p><div class="rule"></div><div class="facts"><div><span>OBSERVED</span><strong>{selected.observed}</strong></div><div><span>MAP STATUS</span><strong>{selected.lat===null?'Not available':'Approximate display point'}</strong></div></div><div class="panel"><p class="eyebrow">PUBLICATION CONTEXT</p><strong>{profile==='community'?'Community-submitted · Community-unreviewed':'Government-sourced · Project-approved'}</strong><p>{profile==='community'?'Published only in the explicitly selected community profile. This is not project approval.':'Included in the named curated release after documented project checks.'}</p></div><div class="panel"><p class="eyebrow">SOURCE NOTE</p><p>{selected.source}. Synthetic content only; no live database or external map tiles are used.</p></div>{/if}</article></div>{/if}<footer><span>Method preview · no live requests</span><a href="/v2-preview/#/locations/{selected?.id ?? ''}?profile={profile}">Copy record route ↗</a></footer></main>
